# list 4-connected components per non-background color, ignore 6; summarize bbox/size
from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v in (0,6) or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); pts=[]
  while q:
   y,x=q.pop();pts.append((y,x))
   for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=yy<R and 0<=xx<C and (yy,xx) not in seen and grid[yy][xx]==v:
     seen.add((yy,xx));q.append((yy,xx))
  comps.append((v,len(pts),min(y for y,x in pts),min(x for y,x in pts),max(y for y,x in pts),max(x for y,x in pts)))
print(comps)

